const $ = (s,root=document)=>root.querySelector(s);
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-10 12 10 6 10-6M2 14l10 6 10-6"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 16-6-6L4 21"/>',check:'<path d="m5 12 4 4L19 6"/>',approval:'<path d="m8 12 3 3 5-6"/><circle cx="12" cy="12" r="9"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--bg)"/><circle cx="16" cy="17" r="3" fill="var(--bg)"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10Z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',folder:'<path d="M3 5h6l2 3h10v13H3Z"/>',retry:'<path d="M3 9a9 9 0 1 1 0 7m0-13v6h6"/>',file:'<path d="M5 2h9l5 5v15H5Zm9 0v6h5M8 13h8m-8 4h6"/>'};
const icon = n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const photos={trench:'https://i.pinimg.com/originals/d2/72/3b/d2723bcd5f0d0e67cbbfacdca982b559.jpg',dress:'https://mediaslide-europe.storage.googleapis.com/munichmodels/pictures/2461/13856/large-1685023707-c6b94c0e00a7072f2bfa7e5fa8bdd79c.jpg',tailoring:'https://images.squarespace-cdn.com/content/v1/5a42ade8cd39c3b435d95e53/4a08f10f-0c6e-474a-975d-d085af0a8a6b/ARKET%2BThe%2Bnew%2Bdenim%2B2.png?format=1000w',evening:'https://mediaslide-europe.storage.googleapis.com/ouimanagement/pictures/1055/2068/large-1701273889-54686c125afad6724f2b876969bb14e6.jpg'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={role:'Producer',theme:'light',brand:{name:'Atelier No. 04',tone:'Quiet confidence. Sculptural silhouettes. An honest expression of material.',avoid:'No changes to garment shape, logos, seams or colour. No dramatic retouching.',background:'Warm stone',lighting:'Soft daylight'},selectedModel:0,projects:[{id:'p1',name:'The art of everyday',season:'Spring / Summer 2027',kind:'On-model imagery',photo:'trench',status:'review',count:12,updated:'Edited 2 hours ago'},{id:'p2',name:'After hours',season:'Evening essentials',kind:'Campaign imagery',photo:'dress',status:'approved',count:8,updated:'Edited yesterday'},{id:'p3',name:'A softer structure',season:'Resort 2027',kind:'On-model imagery',photo:'tailoring',status:'draft',count:6,updated:'Edited yesterday'}],reviews:[{id:'r1',name:'Sculpted trench · Front',photo:'trench',status:'review',score:96,colour:94,detail:98},{id:'r2',name:'Essential dress · Front',photo:'dress',status:'review',score:89,colour:96,detail:83},{id:'r3',name:'Relaxed tailoring · Full length',photo:'tailoring',status:'approved',score:97,colour:97,detail:96}],jobs:[],activity:[{text:'Relaxed tailoring was approved by the studio team.',time:'12 minutes ago'},{text:'The art of everyday is ready for a creative review.',time:'2 hours ago'}]};
let state;try{state=JSON.parse(localStorage.getItem('ordre-studio-v1'))||structuredClone(initial);}catch{state=structuredClone(initial)}
let route='studio',filter='all',search='',draft=null,wizardStep=0,uploadImage=null,selectedFiles=[],toastTimer,activeReview=null;
const canProduce=()=>state.role!=='ORDRE visitor';
const canApprove=()=>['Producer','Administrator'].includes(state.role);
const canAdmin=()=>state.role==='Administrator';
function save(){try{localStorage.setItem('ordre-studio-v1',JSON.stringify(state));}catch{toast('This browser could not save changes. Your current session still works.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4000)}
function activity(text){state.activity.unshift({text,time:'Just now'});state.activity=state.activity.slice(0,25)}
function statusLabel(status){return {review:'Needs review',approved:'Approved',draft:'Draft',generating:'Generating',blocked:'Safety check',failed:'Needs retry',changes:'Changes requested'}[status]||status}
function badge(status){return `<span class="status ${esc(status)}">${statusLabel(status)}</span>`}
const modelNames=['Editorial 01','Sculptural 02','Natural 03','Evening 04'];
function picture(key){return photos[key]||photos.trench}
function init(){document.documentElement.dataset.theme=state.theme;$('#role').value=state.role;$('#theme-button').innerHTML=icon(state.theme==='light'?'moon':'sun');$('#theme-button').setAttribute('aria-label',`Switch to ${state.theme==='light'?'dark':'light'} mode`);$('.notification-button').innerHTML=icon('bell');navigate(location.hash.slice(1)||'studio',false)}
function nav(){const items=[['studio','grid','Overview'],['productions','layers','Productions'],['casting','people','Virtual casting'],['assets','image','Asset library'],['approvals','approval','Review & approval'],['queue','clock','Production queue'],['brand','folder','Brand direction'],['system','settings','Design system']];$('#navigation').innerHTML=items.map(([id,ic,label],i)=>`${i===6?'<div class="nav-separator"></div><p class="nav-label">FOUNDATIONS</p>':''}<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='approvals'?`<span class="nav-count">${state.reviews.filter(r=>r.status==='review').length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=items.find(i=>i[0]===route)?.[2]||'Overview';$('.workspace strong').textContent=state.brand.name}
function navigate(value,focus=true){route=['studio','productions','casting','assets','approvals','queue','brand','system'].includes(value)?value:'studio';filter='all';search='';nav();render();$('#sidebar').classList.remove('open');if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0)}}
function header(eyebrow,title,subtitle,action=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${action}</div>`}
const newButton=()=>`<button class="btn primary" data-action="new" ${!canProduce()?'disabled title="Visitors can view approved work only"':''}>${icon('plus')} New production</button>`;
function projectCard(p){return `<article class="project-card"><button class="project-image-wrap" data-project="${p.id}" aria-label="Open ${esc(p.name)}"><img class="project-image" src="${picture(p.photo)}" alt="Editorial reference for ${esc(p.name)}" loading="lazy">${badge(p.status)}<span class="image-label">${esc(p.season).toUpperCase()}</span></button><div class="project-meta"><div class="project-title-row"><h3><button class="text-button" data-project="${p.id}" style="font:inherit">${esc(p.name)}</button></h3><button class="icon-button" data-project="${p.id}" aria-label="View ${esc(p.name)}">${icon('arrow')}</button></div><p>${esc(p.kind)} <span class="footer-dot">·</span> ${p.count} ${p.status==='draft'?'planned images':'images'}</p><div class="card-bottom"><div class="mini-avatars" aria-label="Studio collaborators"><span class="mini-avatar">YP</span><span class="mini-avatar">AC</span></div><span>${esc(p.updated)}</span></div></div></article>`}
function projectsMarkup(){const projects=state.projects.filter(p=>(state.role!=='ORDRE visitor'||p.status==='approved')&&(filter==='all'||p.status===filter)&&p.name.toLowerCase().includes(search.toLowerCase()));return projects.length?projects.map(projectCard).join(''):`<div class="empty" style="grid-column:1/-1"><h2>A little space for what’s next.</h2><p>${search?'No productions match your search. Try another name.':'No productions in this view. Choose another filter or start a new production.'}</p></div>`}
function projectFilters(){return `<div class="filter-bar" role="group" aria-label="Filter productions">${[['all','All productions'],['review','In review'],['approved','Approved'],['draft','Drafts']].map(([id,title])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${title}${id==='all'?`<span>${state.projects.filter(p=>state.role!=='ORDRE visitor'||p.status==='approved').length}</span>`:''}</button>`).join('')}<span class="filter-spacer"></span><label class="search-box">${icon('search')}<input id="project-search" placeholder="Search productions" aria-label="Search productions" value="${esc(search)}"></label></div>`}
function dashboard(){const approved=state.reviews.filter(r=>r.status==='approved').length,review=state.reviews.filter(r=>r.status==='review').length;return `${header('YOUR CREATIVE WORKSPACE','Good morning, Yash.','A new perspective. The same unmistakable brand.',newButton())}<section class="hero" aria-labelledby="hero-title"><img class="hero-image" src="${photos.trench}" alt="Luxury neutral tailoring editorial reference"><div class="hero-shade"></div><div class="hero-copy"><div class="eyebrow">IMAGINATION, WITH INTENTION</div><h2 id="hero-title">Your vision.<br><em>Beautifully realised.</em></h2><p>From the first creative brief to the final frame.<br>A considered space to bring your collections to life.</p><button class="hero-link" data-action="${canProduce()?'new':'guide'}">${canProduce()?'Create something extraordinary':'Explore the creative process'} ${icon('arrow')}</button></div><span class="hero-number">THE STUDIO EDIT / 001</span><span class="hero-caption">ATELIER NO. 04 &nbsp; — &nbsp; SS / 27</span></section><section class="metrics" aria-label="Workspace summary"><div class="metric"><span class="metric-title">${icon('layers')}Productions</span><div class="metric-data"><strong>${state.projects.filter(p=>state.role!=='ORDRE visitor'||p.status==='approved').length.toString().padStart(2,'0')}</strong><span>In your workspace</span></div></div><div class="metric"><span class="metric-title">${icon('image')}Image previews</span><div class="metric-data"><strong>${state.reviews.length.toString().padStart(2,'0')}</strong><span>Ready to explore</span></div></div><div class="metric"><span class="metric-title">${icon('approval')}Awaiting approval</span><div class="metric-data"><strong>${review.toString().padStart(2,'0')}</strong><span>A human makes the call</span></div></div><div class="metric"><span class="metric-title">${icon('check')}Approved images</span><div class="metric-data"><strong>${approved.toString().padStart(2,'0')}</strong><span>Ready for handoff</span></div></div></section><section><div class="section-head"><h2>Recent productions</h2><a class="text-button" href="#productions">View all productions ${icon('arrow')}</a></div>${projectFilters()}<div class="project-grid" id="projects">${projectsMarkup()}</div></section><div class="activity-strip">${icon('shield')}<span><strong>Your eye is the final word.</strong> Every AI suggestion stays in review until your team approves it.</span><a class="text-button" href="#approvals">Open review ${icon('arrow')}</a></div>`}
function productions(){return `${header('THE COLLECTIONS','Every collection, in focus.','A considered journey from product to approved imagery.',newButton())}${projectFilters()}<div class="project-grid" id="projects">${projectsMarkup()}</div>`}
function modelCards(inWizard=false){return Object.keys(photos).map((photo,i)=>`<button type="button" class="model-card ${(inWizard?draft.model:state.selectedModel)===i?'selected':''}" data-model="${i}" aria-pressed="${(inWizard?draft.model:state.selectedModel)===i}"><img src="${photos[photo]}" alt="Editorial fashion reference ${i+1}" loading="lazy"><span class="model-text"><strong>${modelNames[i]}</strong><small>${['Relaxed confidence · Tailoring','Poised presence · Minimal','Soft expression · Everyday','Sculptural stance · Evening'][i]}</small><small>Reference photography</small></span>${(inWizard?draft.model:state.selectedModel)===i?`<span class="selected-check">${icon('check')}</span>`:''}</button>`).join('')}
function casting(){return `${header('CAST WITH INTENTION','The right presence.','Find a casting direction that feels like your brand.',`<button class="btn primary" data-action="casting-brief" ${!canProduce()?'disabled':''}>${icon('spark')} Write a casting brief</button>`)}<div class="casting-brief">${icon('spark')}<div><h2>Tell us the feeling. We’ll help with the direction.</h2><p>“A relaxed, confident presence. Natural movement. Let the tailoring do the talking.”</p><span class="chip">Natural expression</span><span class="chip">Full-length framing</span><span class="chip">Quiet confidence</span></div></div><div class="section-head"><h2>Curated casting directions</h2><span class="hint">4 editorial references</span></div><div class="model-grid">${modelCards()}</div><p class="help-label">These are reference photographs for a simulated casting experience. No real person is cloned or generated.</p>`}
function assets(){return `${header('THE BRAND ARCHIVE','Everything, in one place.','Editorial references and approved image previews.',`<button class="btn primary" data-action="upload" ${!canProduce()?'disabled':''}>${icon('upload')} Add product</button>`)}<div class="note">A small, curated reference library for this prototype. Uploaded products are used only in this browser session.</div><div class="section-head"><h2>Editorial references</h2><span class="hint">4 images</span></div><div class="assets-grid">${Object.entries(photos).map(([p,u],i)=>`<button class="asset-card" data-asset="${p}"><img src="${u}" alt="${['Neutral trench','Minimal black dress','Relaxed beige tailoring','Sculptural black evening dress'][i]} editorial reference"><span>${['Sculpted trench','Essential dress','Relaxed tailoring','Evening silhouette'][i]}<small>Reference photography · View details ↗</small></span></button>`).join('')}</div>`}
function approvals(){const rows=state.reviews.filter(r=>(state.role!=='ORDRE visitor'||r.status==='approved')&&(filter==='all'||r.status===filter));return `${header('HUMAN IN THE LOOP','Good imagery. Your approval.','Look closely. Make the call. Nothing is approved automatically.',`<button class="btn" data-action="export" ${!state.reviews.some(r=>r.status==='approved')?'disabled':''}>${icon('download')} Export approval report</button>`)}<div class="filter-bar" role="group" aria-label="Filter reviews">${[['all','All images'],['review','Needs review'],['approved','Approved'],['changes','Changes requested']].map(([id,t])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${t}</button>`).join('')}</div>${!canApprove()?`<p class="permission-note">${state.role==='ORDRE visitor'?'Visitor view shows approved images only.':'As an Operator, you can inspect outputs and request changes. A Producer or Administrator gives final approval.'}</p>`:''}<div class="review-grid">${rows.map(r=>`<article class="review-card"><button class="review-img" data-review="${r.id}" aria-label="Inspect ${esc(r.name)}"><img src="${picture(r.photo)}" alt="${esc(r.name)} reference image" loading="lazy"></button><div class="review-info">${badge(r.status)}<h3>${esc(r.name)}</h3><p>Editorial preview · Simulated quality signals</p><div class="rating-row"><span>Suggested product match</span><strong>${r.score}%</strong></div><button class="btn" data-review="${r.id}">${icon('search')} ${r.status==='approved'?'View approved image':'Inspect image'}</button></div></article>`).join('')||'<div class="empty" style="grid-column:1/-1"><h2>You’re all caught up.</h2><p>Choose another view or start a production to see more images.</p></div>'}</div>`}
function queue(){return `${header('FROM BRIEF TO FRAME','A little time. A thoughtful result.','Follow every output, with a clear next step when something needs attention.',newButton())}<div class="note">Prototype mode: generation is simulated. No AI service runs and no credits are charged. Select a scenario in the final step of a new production.</div><div class="row-list">${state.jobs.map(j=>`<article class="job-row"><img class="job-thumb" src="${picture(j.photo)}" alt="Reference for ${esc(j.name)}"><div class="job-content"><h3>${esc(j.name)}</h3><p>${jobCopy(j)}</p>${j.status==='generating'?`<div class="progress" role="progressbar" aria-label="${esc(j.name)} generation" aria-valuenow="${jobProgress(j)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${jobProgress(j)}%"></span></div>`:''}</div><div class="job-actions">${badge(j.status)}${['failed','blocked'].includes(j.status)?`<button class="btn small" data-job="${j.id}" ${!canProduce()?'disabled':''}>${j.status==='blocked'?'Edit brief':icon('retry')+' Retry'}</button>`:''}${j.status==='review'?'<a class="btn small" href="#approvals">Review image →</a>':''}${j.status==='generating'&&canProduce()?`<button class="text-button" data-cancel-job="${j.id}">Cancel</button>`:''}</div></article>`).join('')||`<div class="empty">${icon('spark')}<h2>Your next idea starts here.</h2><p>Start a production and we’ll guide you from a brief to an image ready for review.</p>${newButton()}</div>`}</div>`}
function jobProgress(j){return Math.min(95,Math.round((Date.now()-j.started)/j.duration*100))}
function jobCopy(j){if(j.status==='generating'){return j.scenario==='slow'&&Date.now()-j.started>8000?'This is taking a little longer. Your work is safe; you can keep browsing.':'Composing your preview. You can leave this page; we’ll keep working.'}return {review:'Your preview is ready. A person needs to check it before approval.',failed:'The preview could not finish. Your brief is saved. Retry this image.',blocked:'The simulated safety check paused this request. Review the brief and use a neutral clothing description.',draft:'Generation cancelled. Your brief is saved; start a new production when you’re ready.',approved:'Approved by a person. The decision is recorded in the review history.',changes:'Changes requested. Read the review note before creating another version.'}[j.status]||''}
function brand(){const b=state.brand;return `${header('A DISTINCT POINT OF VIEW','Always, unmistakably you.','Give every production a clear creative starting point.',canAdmin()?'<button class="btn primary" data-action="save-brand">Save brand direction</button>':'<button class="btn" data-action="admin-preview">Preview as Administrator</button>')}<div class="two-columns"><form id="brand-form" class="panel"><h2>Your brand, in your words.</h2><p class="hint">${canAdmin()?'These guidelines become the starting point for every new production.':'Only an Administrator can change shared brand direction.'}</p><label class="field"><span>Brand name</span><input id="brand-name" value="${esc(b.name)}" maxlength="50" ${!canAdmin()?'disabled':''}></label><label class="field"><span>The feeling you want to create</span><textarea id="brand-tone" maxlength="600" ${!canAdmin()?'disabled':''}>${esc(b.tone)}</textarea><small>Describe it as you would to your creative team.</small></label><label class="field"><span>What should never change?</span><textarea id="brand-avoid" maxlength="600" ${!canAdmin()?'disabled':''}>${esc(b.avoid)}</textarea><small>Be specific about product details and retouching boundaries.</small></label><div class="field-row"><label class="field"><span>Background</span><select id="brand-background" ${!canAdmin()?'disabled':''}>${['Warm stone','Pure white','Soft grey'].map(x=>`<option ${x===b.background?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Lighting</span><select id="brand-lighting" ${!canAdmin()?'disabled':''}>${['Soft daylight','Even studio','Gentle contrast'].map(x=>`<option ${x===b.lighting?'selected':''}>${x}</option>`).join('')}</select></label></div></form><div class="stack"><section class="panel"><p class="eyebrow">THE VISUAL LANGUAGE</p><h2>Less, with intention.</h2><div class="swatches" aria-label="Brand palette: ivory, stone, olive and ink"><span class="swatch" style="background:#f6f5f1"></span><span class="swatch" style="background:#d6d1c5"></span><span class="swatch" style="background:#7e8774"></span><span class="swatch" style="background:#292b28"></span></div><p>Quiet neutrals. Honest texture. Space for the product to speak.</p><img src="${photos.tailoring}" alt="Neutral tailoring brand reference" style="width:100%;height:230px;object-fit:cover;object-position:center 25%;border-radius:4px"></section><div class="note">${icon('shield')} Brand guidance helps shape an image. A human review still decides whether it is faithful to the product.</div></div></div>`}
function designSystem(){return `${header('RESTRAINED. CONSISTENT. CONSIDERED.','The studio foundations.','A living design language, built around clarity and trust.',`<button class="btn" data-action="theme">${icon('sun')} Toggle appearance</button>`)}<div class="two-columns"><div class="stack"><section class="panel"><p class="eyebrow">01 / COLOUR & TYPE</p><h2>An editorial rhythm.</h2><div class="font-specimen">Space to create.<br><em>Room to decide.</em></div><div class="swatches"><span class="swatch" style="background:#f6f5f1"></span><span class="swatch" style="background:#e7ede5"></span><span class="swatch" style="background:#344b3d"></span><span class="swatch" style="background:#292b28"></span></div>${[['Canvas','--bg'],['Text','--ink'],['Secondary text','--muted'],['Quiet emphasis','--accent-soft'],['Dividers','--line']].map(([a,b])=>`<div class="token-row"><span>${a}</span><code>${b}</code></div>`).join('')}</section><section class="panel"><p class="eyebrow">02 / SHARED COMPONENTS</p><div class="detail-actions"><button class="btn primary" data-action="new">${icon('plus')} Create</button><button class="btn" data-action="guide">Explore</button><button class="btn" disabled>Unavailable</button></div><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:20px">${['review','approved','generating','blocked','draft'].map(badge).join('')}</div><p class="hint">Visible focus. Semantic labels. Status communicated with words, not colour alone. Reduced motion is respected.</p></section></div><div class="stack"><section class="panel"><p class="eyebrow">03 / MESSAGE LIBRARY</p><div class="note"><strong>Your image is ready for a closer look.</strong>Check the colour, product details and image quality before you approve.</div><div class="note warning"><strong>This is taking a little longer.</strong>Your work is safe. Keep browsing and check the production queue when you’re ready.</div><div class="note error"><strong>We couldn’t finish this image.</strong>Your brief is saved. Retry the image, or adjust the brief first.</div><div class="dark-preview"><strong>Considered after dark.</strong><p>The same tokens and hierarchy, in a quieter palette.</p></div></section><section class="panel"><p class="eyebrow">04 / ROLE PREVIEW</p><table class="role-matrix"><thead><tr><th>Role</th><th>Create</th><th>Approve</th><th>Brand</th></tr></thead><tbody><tr><td>Administrator</td><td>Yes</td><td>Yes</td><td>Edit</td></tr><tr><td>Producer</td><td>Yes</td><td>Yes</td><td>View</td></tr><tr><td>Operator</td><td>Yes</td><td>No</td><td>View</td></tr><tr><td>ORDRE visitor</td><td>No</td><td>No</td><td>View</td></tr></tbody></table><p class="hint">Role switching demonstrates interface permissions. It is not authentication or server-side access control.</p></section></div></div>`}
function render(){const pages={studio:dashboard,productions,casting,assets,approvals,queue,brand,system:designSystem};$('#main').innerHTML=pages[route]();nav()}
function modal(title,subtitle,body,footer='',wide=false){const m=$('#modal');m.style.width=wide?'min(1000px, calc(100% - 32px))':'';m.innerHTML=`<div class="modal-head"><div><p class="eyebrow">ORDRE STUDIO</p><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!m.open)m.showModal()}
function close(){if(draft){if(uploadImage)URL.revokeObjectURL(uploadImage);uploadImage=null;selectedFiles=[]}draft=null;activeReview=null;$('#modal').close()}
function startProduction(preset={}){if(!canProduce()){toast('Visitors can explore approved work. Switch to a production role to create.');return}draft={name:preset.name||'',brief:preset.brief||state.brand.tone,model:state.selectedModel,product:false,productName:'',format:'On-model',scenario:'normal',...preset};uploadImage=null;selectedFiles=[];wizardStep=0;wizard()}
function rememberDraft(){if(!draft)return;if($('#production-name')){draft.name=$('#production-name').value.trim();draft.brief=$('#production-brief').value.trim()}if($('#generation-scenario'))draft.scenario=$('#generation-scenario').value}
function wizard(){const steps=['Direction','Product','Casting','Create'];let body='';if(wizardStep===0){body=`<h3 class="wizard-heading">What are we bringing to life?</h3><p class="wizard-description">Start with a few words. Your brand direction is already here to help.</p><label class="field"><span>Production name</span><input id="production-name" placeholder="e.g. The spring edit" value="${esc(draft.name)}" maxlength="70" required><small>A name your team can find and recognise.</small></label><label class="field"><span>Creative brief</span><textarea id="production-brief" maxlength="1000">${esc(draft.brief)}</textarea><small>Describe the mood, styling and setting in everyday language.</small></label><div class="note">${icon('folder')} Using <strong style="display:inline">${esc(state.brand.name)}</strong> brand direction · ${esc(state.brand.lighting)} · ${esc(state.brand.background)}</div>`}else if(wizardStep===1){body=`<h3 class="wizard-heading">Let’s meet the product.</h3><p class="wizard-description">A clear front photo works best. Keep the whole garment visible, in even light.</p><label class="upload-area">${icon('upload')}<strong>Choose product photographs</strong><span class="hint">JPG, PNG or WebP · Up to 4 images · 5 MB per image</span><input type="file" id="product-upload" accept="image/jpeg,image/png,image/webp" multiple aria-label="Choose product photographs"></label><div id="upload-result">${draft.product?`<div class="upload-preview">${icon('check')} ${esc(draft.productName)} ready for this demo</div>`:''}</div><button class="sample-pick" data-action="sample"><img src="${photos.trench}" alt="Sample trench reference"><span><strong>Just exploring? Use the sample collection.</strong><small>A neutral trench editorial reference. No upload needed.</small></span>${icon(draft.product?'check':'arrow')}</button><p class="hint">Your uploads stay in this browser session. This demo does not send them to an AI service.</p>`}else if(wizardStep===2){body=`<h3 class="wizard-heading">A presence that feels right.</h3><p class="wizard-description">Choose an editorial casting direction. You’ll review the result before anything is approved.</p><div class="model-grid">${modelCards(true)}</div><div class="note">Reference photographs illustrate the casting concept. This demo does not generate a virtual likeness.</div>`}else{body=`<h3 class="wizard-heading">One last look, then create.</h3><p class="wizard-description">Choose your output. Every preview will come back to your team for approval.</p><div class="options-grid">${[['On-model','people','Show the product on a model'],['Packshot','image','Show only the product'],['Detail crop','search','Focus on texture and finish']].map(([f,ic,t])=>`<button class="option ${draft.format===f?'selected':''}" data-format="${f}" aria-pressed="${draft.format===f}">${icon(ic)}<strong>${f}</strong><small>${t}</small></button>`).join('')}</div><ul class="checklist"><li>${icon('check')}<span>${esc(draft.name)} · ${esc(state.brand.name)}</span></li><li>${icon('check')}<span>${esc(draft.productName)} · ${modelNames[draft.model]}</span></li><li>${icon('check')}<span>Preserve the product’s colour, construction and proportions</span></li><li>${icon('shield')}<span>Human approval required for every image</span></li></ul><label class="field"><span>Demo scenario</span><select id="generation-scenario"><option value="normal" ${draft.scenario==='normal'?'selected':''}>Ready for review · about 12 seconds</option><option value="slow" ${draft.scenario==='slow'?'selected':''}>Longer wait · about 35 seconds</option><option value="blocked" ${draft.scenario==='blocked'?'selected':''}>Safety check · guided brief edit</option><option value="failed" ${draft.scenario==='failed'?'selected':''}>Interrupted generation · retry</option></select><small>Simulated outputs use the reference library. No AI generation, paid credits or automatic approval.</small></label>`}modal('A new point of view.','From your creative direction to a considered first frame.',`<div class="stepper" aria-label="Production steps">${steps.map((s,i)=>`<div class="step ${i===wizardStep?'active':i<wizardStep?'complete':''}" ${i===wizardStep?'aria-current="step"':''}><b>${i<wizardStep?'✓':i+1}</b>${s}</div>`).join('')}</div><div class="modal-body">${body}<p id="wizard-error" class="inline-error form-error" role="alert"></p></div>`,`<button class="btn" data-action="${wizardStep===0?'close':'wizard-back'}">${wizardStep===0?'Cancel':'Back'}</button><button class="btn primary" data-action="wizard-next">${wizardStep===3?icon('spark')+' Create preview':'Continue '+icon('arrow')}</button>`,wizardStep===2)}
function wizardNext(){rememberDraft();if(wizardStep===0&&(!draft.name||!draft.brief)){const message=!draft.name?'Give this production a name so your team can find it.':'Add a short creative brief to guide the image.';$('#wizard-error').textContent=message;$(!draft.name?'#production-name':'#production-brief').focus();return}if(wizardStep===1&&!draft.product){$('#wizard-error').textContent='Choose a product photograph or use the sample collection to continue.';return}if(wizardStep<3){wizardStep++;wizard()}else createJob()}
function createJob(){if(!canProduce())return;const d={...draft};const id='job-'+Date.now(),photo=d.productName.startsWith('Sample')?'trench':Object.keys(photos)[d.model];const job={id,name:d.name,brief:d.brief,photo,status:'generating',scenario:d.scenario,format:d.format,started:Date.now(),duration:d.scenario==='slow'?35000:12000};state.jobs.unshift(job);state.projects.unshift({id:'p-'+Date.now(),jobId:id,name:d.name,season:'New production',kind:d.format+' preview',photo,status:'generating',count:1,updated:'Created just now'});activity(`“${d.name}” entered the production queue.`);save();close();location.hash='queue';if(route==='queue')render();toast('Your preview is underway. You can keep exploring the studio.')}
function tick(){let changed=false;for(const j of state.jobs){if(j.status!=='generating')continue;let elapsed=Date.now()-j.started;if(elapsed<j.duration)continue;j.status=j.scenario==='failed'?'failed':j.scenario==='blocked'?'blocked':'review';const p=state.projects.find(p=>p.jobId===j.id);if(p)p.status=j.status;if(j.status==='review'&&!state.reviews.some(r=>r.jobId===j.id)){state.reviews.unshift({id:'r-'+j.id,jobId:j.id,name:j.name+' · '+j.format,photo:j.photo,status:'review',score:94,colour:92,detail:96});activity(`“${j.name}” is ready for human review.`);toast(`“${j.name}” is ready for your review.`)}else activity(`“${j.name}” needs attention: ${statusLabel(j.status).toLowerCase()}.`);changed=true}if(changed){save();nav();if(!$('#modal').open)render()}else if(route==='queue'&&!$('#modal').open&&state.jobs.some(j=>j.status==='generating'))render()}
function review(id){const r=state.reviews.find(r=>r.id===id);if(!r)return;activeReview=id;modal('A closer look.','AI suggests. Your eye decides.',`<div class="modal-body approval-layout"><div><img class="approval-image" src="${picture(r.photo)}" alt="${esc(r.name)} editorial reference"><p class="approval-label">Reference photograph · Simulated output, not an AI-generated product match.</p><button class="text-button" data-action="reference">View product fidelity guide ↗</button></div><div>${badge(r.status)}<h3 style="font:24px Georgia;margin:13px 0">${esc(r.name)}</h3><p class="hint">These sample signals show where to look. They do not replace a product check.</p><div class="rating-row"><span>Colour consistency</span><strong>${r.colour}%</strong></div><div class="progress"><span style="width:${r.colour}%"></span></div><div class="rating-row"><span>Construction & detail</span><strong>${r.detail}%</strong></div><div class="progress"><span style="width:${r.detail}%"></span></div>${r.detail<90?'<div class="note warning"><strong>Take a closer look at the hem.</strong>The sample detail signal is lower. Inspect the seam and silhouette before deciding.</div>':''}${['colour','detail','quality'].map((v,i)=>`<label class="review-check"><input type="checkbox" name="review-check" value="${v}" ${r.status==='approved'?'checked disabled':''}><span>${['Colour and material feel faithful','Shape, seams and details are correct','Framing and overall quality are ready'][i]}<small>${['Compare against the original product photograph.','Check proportions, fastenings and any branding.','Check the face, hands, background and crop.'][i]}</small></span></label>`).join('')}<label class="field"><span>Review note</span><textarea class="review-comments" id="review-note" placeholder="What works? What needs another pass?" maxlength="500" ${r.status==='approved'||state.role==='ORDRE visitor'?'disabled':''}>${esc(r.note||'')}</textarea></label><p class="inline-error" id="review-error" role="alert"></p><p class="hint">${canApprove()?'Your approval is recorded in this local prototype.':state.role==='Operator'?'An Administrator or Producer must give final approval.':'Visitor access is read-only.'}</p></div></div>`,`<button class="btn" data-action="close">Close</button><div class="detail-actions">${r.status!=='approved'&&state.role!=='ORDRE visitor'?`<button class="btn" data-action="request-changes">Request changes</button><button class="btn primary" data-action="approve" ${!canApprove()?'disabled':''}>${icon('check')} Approve image</button>`:''}</div>`,true)}
function decide(approved){const r=state.reviews.find(r=>r.id===activeReview);if(!r||state.role==='ORDRE visitor'||approved&&!canApprove())return;if(approved&&document.querySelectorAll('input[name="review-check"]:checked').length<3){$('#review-error').textContent='Check all three quality points before approving this image.';return}const note=$('#review-note').value.trim();if(!approved&&!note){$('#review-error').textContent='Tell the studio what needs to change before requesting another pass.';$('#review-note').focus();return}r.status=approved?'approved':'changes';r.note=note;r.reviewedBy=state.role;r.reviewedAt=new Date().toISOString();const job=state.jobs.find(j=>j.id===r.jobId);if(job){job.status=r.status;const p=state.projects.find(p=>p.jobId===job.id);if(p)p.status=r.status}activity(`${r.name}: ${approved?'approved':'changes requested'} by ${state.role}.`);save();close();render();toast(approved?'Image approved. Your decision is recorded.':'Changes requested. Your note is attached to the image.')}
function showProject(id){const p=state.projects.find(p=>p.id===id);if(!p)return;modal(esc(p.name),`${esc(p.season)} · ${esc(p.kind)}`,`<div class="modal-body approval-layout"><img class="approval-image" src="${picture(p.photo)}" alt="${esc(p.name)} editorial reference"><div>${badge(p.status)}<h3 class="wizard-heading" style="margin-top:20px">The creative direction</h3><p>${esc(state.brand.tone)}</p><ul class="checklist"><li>${icon('image')}${p.count} ${p.status==='draft'?'planned images':'collection images'}</li><li>${icon('people')}${modelNames[state.selectedModel]}</li><li>${icon('sun')}${esc(state.brand.lighting)}</li><li>${icon('shield')}Human approval at every handoff</li></ul><p class="hint">Seeded collection counts are example planning data. The review screen contains the available interactive sample images.</p></div></div>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-project-next="${p.id}">${p.status==='draft'?'Continue production':'Open review'} ${icon('arrow')}</button>`,true)}
function guide(){modal('A studio built around people.','An independent workflow concept by Yash Patel.',`<div class="modal-body"><ol class="guide-list"><li><strong>Set a clear creative direction.</strong><p>Visit Brand direction. Switch to Administrator to edit the shared brief and visual guardrails.</p></li><li><strong>Create a production.</strong><p>Add a brief, choose a sample or upload product photographs, then select a casting direction.</p></li><li><strong>Explore uncertainty.</strong><p>Choose a normal, slow, interrupted or safety-check scenario. Follow the queue and see a clear next step.</p></li><li><strong>Make the final call.</strong><p>Inspect a preview, check three quality points and approve it, or request changes with a review note.</p></li><li><strong>See the same studio through different roles.</strong><p>Use the role menu to explore Administrator, Producer, Operator and ORDRE visitor interfaces.</p></li></ol><div class="note">This is a browser-local prototype. It uses reference photographs and scripted AI states. It does not provide image generation, authentication, shared team storage or compliance guarantees.</div></div>`,`<button class="btn" data-action="close">Back to studio</button><button class="btn primary" data-action="new">Try a production ${icon('arrow')}</button>`)}
function about(){modal('Designed with intention.','An independent ORDRE-inspired concept by Yash Patel.',`<div class="modal-body"><h3 class="wizard-heading">Complex workflows. A calmer experience.</h3><p>This prototype explores the full journey from a brand brief through casting, production and human approval. It is an independent portfolio demonstration and is not affiliated with or endorsed by ORDRE.</p><div class="note">Reference images are existing editorial photography. All AI generation, quality percentages, collaborators and collection figures are sample data. Uploads remain in memory for the current session; other demo choices are stored locally in your browser.</div><p class="attribution">Image references: <a href="https://www.pinterest.com/pin/63965257206203162/" target="_blank" rel="noopener noreferrer">Vogue Germany reference via Pinterest</a>, <a href="https://www.munich-models.de/main/2461-valeria-chenskaya/13856-overview/" target="_blank" rel="noopener noreferrer">Munich Models</a>, <a href="https://www.varsno.com/arketdenim" target="_blank" rel="noopener noreferrer">Vårsnö / ARKET</a>, <a href="https://www.ouimanagement.com/image/1055-daria-strokous" target="_blank" rel="noopener noreferrer">Oui Management</a>. Rights remain with their respective owners.</p><div class="about-links"><a class="btn" href="https://github.com/yashvinodbhaipatel/ordre-ai-studio-demo" target="_blank" rel="noopener noreferrer">View source ↗</a><button class="btn" data-action="guide">Explore the workflow</button><button class="btn" data-action="reset-prompt">Reset demo</button></div></div>`,`<span class="hint">Concept, UX and development · Yash Patel</span><button class="btn primary" data-action="close">Back to studio</button>`)}
function saveBrand(){if(!canAdmin())return;const name=$('#brand-name').value.trim(),tone=$('#brand-tone').value.trim(),avoid=$('#brand-avoid').value.trim();if(!name||!tone){toast('Add a brand name and creative direction before saving.');return}state.brand={name,tone,avoid,background:$('#brand-background').value,lighting:$('#brand-lighting').value};activity('Shared brand direction was updated by Administrator.');save();render();toast('Brand direction saved. New productions will use these guidelines.')}
function exportReport(){const approved=state.reviews.filter(r=>r.status==='approved');const csv=[['ORDRE Studio independent concept — simulated approval report'],['Image','Status','Reviewer','Reviewed at','Note'],...approved.map(r=>[r.name,r.status,r.reviewedBy||'Studio team (sample)',r.reviewedAt||'Seeded example',r.note||''])].map(row=>row.map(v=>'"'+String(/^[=+@\-\t\r]/.test(String(v))?"'"+v:v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='ordre-studio-approval-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);toast(`Approval report downloaded for ${approved.length} image${approved.length===1?'':'s'}.`)}
function handleAction(action){switch(action){case'new':startProduction();break;case'close':close();break;case'menu':$('#sidebar').classList.toggle('open');break;case'theme':state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;$('#theme-button').innerHTML=icon(state.theme==='light'?'moon':'sun');$('#theme-button').setAttribute('aria-label',`Switch to ${state.theme==='light'?'dark':'light'} mode`);save();break;case'guide':guide();break;case'about':about();break;case'wizard-next':wizardNext();break;case'wizard-back':rememberDraft();wizardStep--;wizard();break;case'sample':draft.product=true;draft.productName='Sample trench collection';uploadImage=null;selectedFiles=[];wizard();break;case'approve':decide(true);break;case'request-changes':decide(false);break;case'save-brand':saveBrand();break;case'export':exportReport();break;case'admin-preview':state.role='Administrator';$('#role').value=state.role;save();render();break;case'upload':startProduction({name:'Product study'});wizardStep=1;wizard();break;case'casting-brief':modal('Who should bring it to life?','Describe a presence, not a technical prompt.',`<div class="modal-body"><label class="field"><span>Your casting brief</span><textarea id="casting-text" placeholder="e.g. A calm, confident presence, natural expression and relaxed movement."></textarea><small>Focus on expression, pose and how the clothing should feel.</small></label><div id="casting-results"></div></div>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-action="suggest-casting">Suggest a direction ${icon('spark')}</button>`);break;case'suggest-casting':{const value=$('#casting-text').value.trim();if(!value){toast('Describe the mood or movement you have in mind.');return}const index=/evening|dramatic|sculptur/i.test(value)?3:/natural|soft|relax/i.test(value)?2:0;state.selectedModel=index;save();$('#casting-results').innerHTML=`<div class="note"><strong>${modelNames[index]} could be a starting point.</strong>This scripted suggestion connects your mood words with a reference direction. You can change it in the casting library.</div>`;break}case'activity':modal('In the studio.','Recent decisions and production updates.',`<div class="modal-body">${state.activity.map(a=>`<div class="activity-item">${esc(a.text)}<small>${esc(a.time)}</small></div>`).join('')}</div>`,`<span class="hint">Sample activity · Stored in this browser</span><button class="btn" data-action="close">Close</button>`);break;case'reference':toast('Compare your original photo: colour, material, seams, buttons, logos, proportions and crop.');break;case'reset-prompt':modal('Start with a fresh studio?','This resets only the sample data in this browser.',`<div class="modal-body"><p>Your demo productions, reviews and brand edits will be replaced with the original sample collection.</p></div>`,`<button class="btn" data-action="close">Keep my changes</button><button class="btn primary" data-action="reset">Reset demo</button>`);break;case'reset':state=structuredClone(initial);save();close();init();toast('The original sample studio is ready.');break}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){handleAction(a.dataset.action);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}const p=e.target.closest('[data-project]');if(p){showProject(p.dataset.project);return}const r=e.target.closest('[data-review]');if(r){review(r.dataset.review);return}const m=e.target.closest('[data-model]');if(m){if(!canProduce()){toast('Casting is read-only for visitors.');return}const i=Number(m.dataset.model);if(draft){draft.model=i;wizard()}else{state.selectedModel=i;save();render();toast(`${modelNames[i]} selected for your next production.`)}return}const format=e.target.closest('[data-format]');if(format){rememberDraft();draft.format=format.dataset.format;wizard();return}const n=e.target.closest('[data-project-next]');if(n){const p=state.projects.find(p=>p.id===n.dataset.projectNext);close();if(p.status==='draft')startProduction({name:p.name});else{location.hash='approvals';if(route==='approvals')render()}return}const j=e.target.closest('[data-job]');if(j){if(!canProduce())return;const job=state.jobs.find(x=>x.id===j.dataset.job);if(job.status==='blocked'){startProduction({name:job.name+' · revised',brief:'A neutral studio photograph showing the clothing clearly.',scenario:'normal'});return}job.started=Date.now();job.duration=12000;job.scenario='normal';job.status='generating';const p=state.projects.find(p=>p.jobId===job.id);if(p)p.status='generating';save();render();toast('Retry started. Your original brief has been kept.');return}const cancel=e.target.closest('[data-cancel-job]');if(cancel){if(!canProduce())return;const job=state.jobs.find(j=>j.id===cancel.dataset.cancelJob);job.status='draft';const p=state.projects.find(p=>p.jobId===job.id);if(p)p.status='draft';activity(`“${job.name}” was cancelled. The brief was kept.`);save();render();return}const asset=e.target.closest('[data-asset]');if(asset){const key=asset.dataset.asset;modal('A reference, thoughtfully chosen.','Editorial photography for the concept library.',`<div class="modal-body"><img src="${picture(key)}" alt="Selected fashion reference" style="max-height:60vh;max-width:100%;display:block;margin:auto"><p class="hint">Existing editorial image, not AI-generated. Original credits are listed in About this prototype.</p></div>`,`<button class="btn" data-action="about">Image credits</button><button class="btn primary" data-action="close">Close</button>`)}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){search=e.target.value;$('#projects').innerHTML=projectsMarkup()}});
document.addEventListener('change',async e=>{if(e.target.id==='role'){state.role=e.target.value;save();if($('#modal').open)close();render();toast(`Previewing as ${state.role}.`)}if(e.target.id==='product-upload'){const files=Array.from(e.target.files||[]);if(!files.length)return;if(files.length>4||files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024)){$('#upload-result').innerHTML='<p class="inline-error" role="alert">Choose up to 4 JPG, PNG or WebP images, each smaller than 5 MB.</p>';e.target.value='';draft.product=false;return}selectedFiles=files;draft.product=true;draft.productName=files.length===1?files[0].name:`${files.length} product photos`;if(uploadImage)URL.revokeObjectURL(uploadImage);uploadImage=URL.createObjectURL(files[0]);$('#upload-result').innerHTML=`<div class="upload-preview"><img src="${uploadImage}" alt="Your uploaded product preview"><span>${esc(draft.productName)}<br><small>Ready · Kept in this session only</small></span>${icon('check')}</div>`}});
document.addEventListener('submit',e=>e.preventDefault());
$('#modal').addEventListener('cancel',()=>{draft=null;activeReview=null;selectedFiles=[];if(uploadImage)URL.revokeObjectURL(uploadImage);uploadImage=null});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open')});
init();tick();setInterval(tick,1000);
